const React = require("react");
const {
  checkPreparation,
  schedulePreparationRetry,
  cancelPreparationRetry,
} = require("./preparation-api.js");

function usePreparation(initialToken) {
  const state = React.useRef({
    visible: true,
    loading: false,
    retryScheduled: false,
    checkCount: 0,
    completed: [],
    token: initialToken,
  });
  const mounted = React.useRef(true);
  const lifecycle = React.useRef(0);
  const retry = React.useRef(null);
  const [, render] = React.useReducer((value) => value + 1, 0);

  const publish = () => render();

  React.useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      lifecycle.current += 1;
      if (retry.current !== null) {
        cancelPreparationRetry(retry.current);
        retry.current = null;
      }
    };
  }, []);

  const checkLifecycle = (requestToken, requestLifecycle) => {
    if (!mounted.current || requestLifecycle !== lifecycle.current) return;

    state.current.loading = true;
    state.current.checkCount += 1;
    publish();
    checkPreparation(requestToken).then((status) => {
      if (!mounted.current || requestLifecycle !== lifecycle.current) return;

      if (status) {
        retry.current = null;
        state.current.loading = false;
        state.current.retryScheduled = false;
        if (!state.current.completed.includes(requestToken)) {
          state.current.completed.push(requestToken);
        }
        publish();
        return;
      }

      retry.current = schedulePreparationRetry(() => {
        retry.current = null;
        checkLifecycle(requestToken, requestLifecycle);
      });
      state.current.retryScheduled = true;
      publish();
    });
  };

  const check = () => {
    if (retry.current !== null) {
      cancelPreparationRetry(retry.current);
      retry.current = null;
    }
    state.current.retryScheduled = false;
    lifecycle.current += 1;
    checkLifecycle(state.current.token, lifecycle.current);
  };

  return {
    start: check,
    close() {
      state.current.visible = false;
      publish();
    },
    reopen(nextToken) {
      state.current.token = nextToken;
      state.current.visible = true;
      publish();
      check();
    },
    snapshot() {
      return { ...state.current, completed: [...state.current.completed] };
    },
  };
}

module.exports = { usePreparation };

